import json, subprocess
from pathlib import Path
refs = subprocess.check_output(['git','for-each-ref','--format=%(refname:short)','refs/remotes/origin/opencode-checkpoints','refs/remotes/origin/opencode-resume']).decode().splitlines()
records=[]
for ref in refs:
    try:
        raw=subprocess.check_output(['git','show',f'{ref}:.omgithub/conversation.json'],stderr=subprocess.DEVNULL)
        data=json.loads(raw)
    except Exception:
        continue
    for i,m in enumerate(data.get('messages', [])):
        if m.get('type')=='user' and isinstance(m.get('text'),str) and m['text'].strip():
            records.append({'ref':ref,'index':i,'text':m['text'].strip()})
Path('/tmp/opencode').mkdir(exist_ok=True)
Path('/tmp/opencode/historical-users.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))
unique={}
for r in records: unique.setdefault(r['text'],[]).append((r['ref'],r['index']))
print(f'Refs: {len(refs)}; user messages: {len(records)}; unique exact messages: {len(unique)}')
for n,(text,where) in enumerate(unique.items(),1):
    short=' '.join(text.split())
    print(f'[{n}] {len(text)} chars | {len(where)} copies | {where[-1]}\n{short[:1000]}\n')
